    'terms_title': 'Terms of Service',
    'terms_last_update': 'Last updated: {year}',
    'terms_s1_title': '1. Acceptance of terms',
    'terms_s1_body':
        'By creating an account or using Binome, you agree to these Terms of Service. If you do not agree, please do not use the app.',
    'terms_s2_title': '2. Who can use Binome',
    'terms_s2_body':
        'Binome is intended for people aged 16 and older, in the context of a freely consented couple relationship. Each account is personal; sharing credentials is prohibited.',
    'terms_s3_title': '3. Your account',
    'terms_s3_body':
        'You are responsible for keeping your credentials confidential and for any activity carried out from your account. Notify us immediately in case of unauthorized access.',
    'terms_s4_title': '4. The couple link ("Box")',
    'terms_s4_body':
        'Joining or creating a Box creates a link exclusive to two people. You can end this link at any time from Settings → Danger zone; shared content (poems, photos, game answers...) is then permanently deleted.',
    'terms_s5_title': '5. Content you share',
    'terms_s5_body1':
        'You remain the owner of the content you send to your binôme (messages, photos, poems, game answers). You only grant us the technical right to host it and deliver it to your binôme, never to use it for other purposes.',
    'terms_s5_body2':
        "You agree not to send content that is illegal, harassing, or that infringes a third party's rights.",
    'terms_s6_title': '6. Virtual coins and purchases',
    'terms_s6_body':
        'Binome offers purchasable virtual coins, usable for certain Shop features. Purchases are processed by our third-party payment provider. Coins have no real monetary value and are neither refundable nor transferable, except where required by law.',
    'terms_s7_title': '7. Suspension and termination',
    'terms_s7_body':
        'We may suspend or delete an account in case of a clear violation of these terms (illegal content, harassment, fraud). You can delete your account at any time from Settings → Danger zone.',
    'terms_s8_title': '8. Service availability',
    'terms_s8_body':
        'We do our best to keep Binome available, without guaranteeing uninterrupted availability. The service may evolve, be temporarily interrupted for maintenance, or be modified.',
    'terms_s9_title': '9. Limitation of liability',
    'terms_s9_body':
        'Binome is provided "as is". To the extent permitted by law, we are not liable for indirect damages resulting from the use of the app.',
    'terms_s10_title': '10. Changes',
    'terms_s10_body':
        'These terms may evolve; any substantial change will be notified to you within the app.',
    'terms_s11_title': '11. Contact',
    'terms_s11_body':
        'For any question about these terms: contact@binome-app.com.',
