    'terms_title': 'Nutzungsbedingungen',
    'terms_last_update': 'Zuletzt aktualisiert: {year}',
    'terms_s1_title': '1. Annahme der Bedingungen',
    'terms_s1_body':
        'Durch das Erstellen eines Kontos oder die Nutzung von Binome stimmst du diesen Nutzungsbedingungen zu. Falls du nicht einverstanden bist, nutze die App bitte nicht.',
    'terms_s2_title': '2. Wer Binome nutzen darf',
    'terms_s2_body':
        'Binome richtet sich an Personen ab 16 Jahren im Rahmen einer frei vereinbarten Paarbeziehung. Jedes Konto ist persönlich; das Teilen von Zugangsdaten ist untersagt.',
    'terms_s3_title': '3. Dein Konto',
    'terms_s3_body':
        'Du bist für die Vertraulichkeit deiner Zugangsdaten und für jede Aktivität über dein Konto verantwortlich. Informiere uns sofort bei unbefugtem Zugriff.',
    'terms_s4_title': '4. Die Paarverbindung („Box“)',
    'terms_s4_body':
        'Der Beitritt zu oder die Erstellung einer Box schafft eine exklusive Verbindung zwischen zwei Personen. Ihr könnt diese Verbindung jederzeit über Einstellungen → Gefahrenzone beenden; geteilte Inhalte (Gedichte, Fotos, Spielantworten...) werden dann endgültig gelöscht.',
    'terms_s5_title': '5. Inhalte, die du teilst',
    'terms_s5_body1':
        'Du bleibst Eigentümer·in der Inhalte, die du deinem Binôme sendest (Nachrichten, Fotos, Gedichte, Spielantworten). Du gewährst uns nur das technische Recht, sie zu hosten und an dein Binôme zu übermitteln, niemals sie anderweitig zu nutzen.',
    'terms_s5_body2':
        'Du verpflichtest dich, keine rechtswidrigen, belästigenden Inhalte oder Inhalte zu senden, die Rechte Dritter verletzen.',
    'terms_s6_title': '6. Virtuelle Münzen und Käufe',
    'terms_s6_body':
        'Binome bietet käufliche virtuelle Münzen an, die für bestimmte Shop-Funktionen genutzt werden können. Käufe werden von unserem externen Zahlungsdienstleister abgewickelt. Münzen haben keinen realen Geldwert und sind weder erstattungsfähig noch übertragbar, außer wenn gesetzlich vorgeschrieben.',
    'terms_s7_title': '7. Sperrung und Kündigung',
    'terms_s7_body':
        'Wir können ein Konto bei eindeutigem Verstoß gegen diese Bedingungen (illegale Inhalte, Belästigung, Betrug) sperren oder löschen. Du kannst dein Konto jederzeit über Einstellungen → Gefahrenzone löschen.',
    'terms_s8_title': '8. Verfügbarkeit des Dienstes',
    'terms_s8_body':
        'Wir bemühen uns, Binome verfügbar zu halten, ohne eine unterbrechungsfreie Verfügbarkeit zu garantieren. Der Dienst kann sich weiterentwickeln, für Wartungsarbeiten vorübergehend unterbrochen oder geändert werden.',
    'terms_s9_title': '9. Haftungsbeschränkung',
    'terms_s9_body':
        'Binome wird „wie besehen" bereitgestellt. Soweit gesetzlich zulässig, haften wir nicht für indirekte Schäden, die aus der Nutzung der App entstehen.',
    'terms_s10_title': '10. Änderungen',
    'terms_s10_body':
        'Diese Bedingungen können sich weiterentwickeln; jede wesentliche Änderung wird dir in der App mitgeteilt.',
    'terms_s11_title': '11. Kontakt',
    'terms_s11_body':
        'Bei Fragen zu diesen Bedingungen: contact@binome-app.com.',
    'common_enable': 'Aktivieren',
    'notif_card_title': 'Benachrichtigungen deaktiviert',
    'notif_card_subtitle':
        'Aktiviere sie, um nichts von deinem Binôme zu verpassen.',
    'notif_dialog_title': 'Aktiviere deine Benachrichtigungen',
    'notif_dialog_subtitle': 'Damit du dein Binôme nie verpasst',
    'notif_dialog_benefit_dates': 'Besondere Daten',
    'notif_dialog_benefit_heartbeats': 'Herzschläge',
    'notif_dialog_benefit_gifts': 'Geschenke',
    'common_cancel': 'Abbrechen',
    'contact_title': 'Kontaktiere uns',
    'contact_subtitle':
        'Eine Frage, ein Problem, ein Vorschlag? Schreib uns, wir antworten per E-Mail.',
    'contact_subject_label': 'Betreff',
    'contact_message_label': 'Nachricht',
    'contact_send': 'Senden',
    'contact_sent_snackbar':
        'Nachricht gesendet — wir antworten dir per E-Mail. 💕',
    'contact_generic_error':
        'Die Nachricht kann derzeit nicht gesendet werden.',
    'privacy_title': 'Datenschutzrichtlinie',
    'privacy_last_update': 'Zuletzt aktualisiert: {year}',
    'privacy_s1_title': '1. Wer wir sind',
    'privacy_s1_body1':
        'Binome ist eine mobile App für Paare, konzipiert als privater Raum, der ausschließlich zwei Personen vorbehalten ist. Diese Richtlinie erklärt, welche Daten wir erheben, warum, und wie du sie kontrollieren kannst.',
    'privacy_s1_body2': 'Bei Fragen zu deinen Daten: contact@binome-app.com.',
    'privacy_s2_title': '2. Welche Daten wir erheben',
    'privacy_s2_sub1_title': 'Kontoinformationen',
    'privacy_s2_sub1_body':
        'E-Mail, Vorname, Nachname, Geschlecht, Wohnsitzland, Profilbild, bevorzugte Sprache und Design. Wenn du dich über Google anmeldest, stammen einige dieser Informationen direkt von deinem Google-Konto.',
    'privacy_s2_sub2_title': 'Informationen zu eurem Paar („Box“)',
    'privacy_s2_sub2_body':
        'Euer Verbindungscode, euer „zusammen seit“-Datum, ein Paarfoto, ein gemeinsames Motto/Zitat und eure Erinnerungseinstellungen (Abend-/Morgenrituale).',
    'privacy_s2_sub3_title': 'Inhalte, die ihr austauscht',
    'privacy_s2_sub3_body':
        'Gedichte, Geschenke, Nachrichten, Fotos, Spielantworten, Reaktionen — alles, was du deinem Binôme innerhalb der App sendest.',
    'privacy_s2_sub4_title': 'Zahlungsdaten',
    'privacy_s2_sub4_body':
        'Wenn du virtuelle Münzen kaufst, werden Zahlungsinformationen direkt von unserem externen Zahlungsdienstleister verarbeitet; wir speichern niemals deine vollständigen Bankdaten, nur deinen Transaktionsverlauf (Betrag, Währung, Datum).',
    'privacy_s2_sub5_title': 'Technische Daten',
    'privacy_s2_sub5_body':
        'Push-Benachrichtigungstoken (um dir Erinnerungen zu senden), Zeitstempel der letzten Aktivität sowie Geräteinformationen, die für den ordnungsgemäßen Betrieb des Dienstes erforderlich sind.',
    'privacy_s3_title': '3. Wie wir diese Daten nutzen',
    'privacy_s3_bullet1': '• Um dein Konto und euren Paar-Bereich zu betreiben',
    'privacy_s3_bullet2':
        '• Um dir aktivierte Benachrichtigungen zu senden (Erinnerungen, Hinweise)',
    'privacy_s3_bullet3': '• Um deine Käufe virtueller Münzen zu verarbeiten',
    'privacy_s3_bullet4':
        '• Um die Sicherheit zu gewährleisten und Missbrauch zu verhindern',
    'privacy_s3_bullet5': '• Um die App zu verbessern',
    'privacy_s3_note':
        '\nWir nutzen eure Paar-Inhalte (Nachrichten, Gedichte, Fotos) niemals für Werbung oder KI-generierte Inhalte.',
    'privacy_s4_title': '4. Weitergabe an Dritte',
    'privacy_s4_intro':
        'Deine Daten können, streng im erforderlichen Rahmen, weitergegeben werden an:',
    'privacy_s4_bullet1':
