    'terms_title': 'Términos de servicio',
    'terms_last_update': 'Última actualización: {year}',
    'terms_s1_title': '1. Aceptación de las condiciones',
    'terms_s1_body':
        'Al crear una cuenta o usar Binome, aceptas estos Términos de servicio. Si no estás de acuerdo, por favor no uses la aplicación.',
    'terms_s2_title': '2. Quién puede usar Binome',
    'terms_s2_body':
        'Binome está destinado a personas de 16 años o más, en el marco de una relación de pareja libremente consentida. Cada cuenta es personal; se prohíbe compartir credenciales.',
    'terms_s3_title': '3. Tu cuenta',
    'terms_s3_body':
        'Eres responsable de mantener la confidencialidad de tus credenciales y de cualquier actividad realizada desde tu cuenta. Notifícanos de inmediato en caso de acceso no autorizado.',
    'terms_s4_title': '4. El vínculo de pareja («Box»)',
    'terms_s4_body':
        'Unirse a una Box o crearla establece un vínculo exclusivo entre dos personas. Podéis romper este vínculo en cualquier momento desde Ajustes → Zona de peligro; el contenido compartido (poemas, fotos, respuestas de juegos...) se elimina entonces definitivamente.',
    'terms_s5_title': '5. Contenido que compartes',
    'terms_s5_body1':
        'Conservas la propiedad del contenido que envías a tu binôme (mensajes, fotos, poemas, respuestas de juegos). Solo nos concedes el derecho técnico de alojarlo y transmitirlo a tu binôme, nunca de usarlo con otros fines.',
    'terms_s5_body2':
        'Te comprometes a no enviar contenido ilegal, acosador o que infrinja los derechos de terceros.',
    'terms_s6_title': '6. Monedas virtuales y compras',
    'terms_s6_body':
        'Binome ofrece monedas virtuales comprables, utilizables para ciertas funciones de la Tienda. Las compras son procesadas por nuestro proveedor de pagos externo. Las monedas no tienen valor monetario real y no son reembolsables ni transferibles, salvo obligación legal en contrario.',
    'terms_s7_title': '7. Suspensión y cancelación',
    'terms_s7_body':
        'Podemos suspender o eliminar una cuenta en caso de infracción manifiesta de estas condiciones (contenido ilegal, acoso, fraude). Puedes eliminar tu cuenta en cualquier momento desde Ajustes → Zona de peligro.',
    'terms_s8_title': '8. Disponibilidad del servicio',
    'terms_s8_body':
        'Hacemos todo lo posible por mantener Binome disponible, sin garantizar una disponibilidad ininterrumpida. El servicio puede evolucionar, interrumpirse temporalmente por mantenimiento o modificarse.',
    'terms_s9_title': '9. Limitación de responsabilidad',
    'terms_s9_body':
        'Binome se ofrece «tal cual». En la medida permitida por la ley, no somos responsables de los daños indirectos derivados del uso de la aplicación.',
    'terms_s10_title': '10. Modificaciones',
    'terms_s10_body':
        'Estas condiciones pueden evolucionar; cualquier cambio sustancial te será notificado dentro de la aplicación.',
    'terms_s11_title': '11. Contacto',
    'terms_s11_body':
        'Para cualquier pregunta sobre estas condiciones: contact@binome-app.com.',
