    'terms_s3_body': '你有责任对账户凭证保密，并对通过你的账户进行的任何活动负责。如发现未经授权的访问，请立即通知我们。',
    'terms_s4_title': '4. 情侣连接（"Box"）',
    'terms_s4_body':
        '加入或创建一个 Box 会建立两人专属的连接。你可以随时通过"设置 → 危险区域"结束该连接；届时共享内容（诗歌、照片、游戏回答等）将被永久删除。',
    'terms_s5_title': '5. 你分享的内容',
    'terms_s5_body1':
        '你发送给对方的内容（消息、照片、诗歌、游戏回答）的所有权仍归你所有。你仅授予我们托管并传送给你对方的技术权利，绝不会用于其他目的。',
    'terms_s5_body2': '你同意不发送非法、骚扰性或侵犯第三方权利的内容。',
    'terms_s6_title': '6. 虚拟金币与购买',
    'terms_s6_body':
        'Binome 提供可购买的虚拟金币，可用于商店的部分功能。购买由我们的第三方支付服务商处理。金币没有真实货币价值，除法律另有规定外，不可退款或转让。',
    'terms_s7_title': '7. 暂停与终止',
    'terms_s7_body':
        '如出现明显违反本条款的行为（非法内容、骚扰、欺诈），我们可暂停或删除账户。你可以随时通过"设置 → 危险区域"删除自己的账户。',
    'terms_s8_title': '8. 服务可用性',
    'terms_s8_body': '我们会尽力保持 Binome 的可用性，但不保证服务不间断。服务可能会演变、因维护而暂时中断或被修改。',
    'terms_s9_title': '9. 责任限制',
    'terms_s9_body': 'Binome 按"现状"提供。在法律允许的范围内，我们对因使用本应用而产生的间接损害不承担责任。',
