    'privacy_last_update': '最后更新：{year}',
    'privacy_s1_title': '1. 我们是谁',
    'privacy_s1_body1':
        'Binome 是一款专为情侣设计的移动应用，旨在为两个人保留一个私密专属的空间。本政策说明我们收集哪些数据、原因是什么，以及你如何进行控制。',
    'privacy_s1_body2': '如对你的数据有任何疑问，请联系：contact@binome-app.com。',
    'privacy_s2_title': '2. 我们收集的数据',
    'privacy_s2_sub1_title': '账户信息',
    'privacy_s2_sub1_body':
        '邮箱、名字、姓氏、性别、居住国家、头像、偏好语言和主题。如果你通过 Google 登录，部分信息将直接来自你的 Google 账户。',
    'privacy_s2_sub2_title': '与你们情侣空间（"Box"）相关的信息',
    'privacy_s2_sub2_body': '配对码、"在一起的日期"、情侣照片、共同的座右铭/引言，以及你的提醒偏好（晚间/晨间仪式）。',
    'privacy_s2_sub3_title': '你们交换的内容',
    'privacy_s2_sub3_body': '诗歌、礼物、消息、照片、游戏回答、反应——你在应用内发送给对方的一切内容。',
    'privacy_s2_sub4_title': '支付数据',
    'privacy_s2_sub4_body':
        '如果你购买虚拟金币，支付信息将直接由我们的第三方支付服务商处理；我们绝不存储你完整的银行信息，仅保存你的交易记录（金额、货币、日期）。',
    'privacy_s2_sub5_title': '技术数据',
    'privacy_s2_sub5_body': '推送通知令牌（用于向你发送提醒）、最后活动时间戳，以及服务正常运行所需的设备信息。',
    'privacy_s3_title': '3. 我们如何使用这些数据',
    'privacy_s3_bullet1': '• 运行你的账户和你们的情侣空间',
    'privacy_s3_bullet2': '• 向你发送你已启用的通知（提醒、警报）',
    'privacy_s3_bullet3': '• 处理你的虚拟金币购买',
    'privacy_s3_bullet4': '• 确保安全并防止滥用',
    'privacy_s3_bullet5': '• 改进应用',
    'privacy_s3_note': '\n我们绝不将你们的情侣交流内容（消息、诗歌、照片）用于广告或 AI 生成内容。',
    'privacy_s4_title': '4. 与第三方共享',
    'privacy_s4_intro': '在严格必要的范围内，你的数据可能会共享给：',
    'privacy_s4_bullet1': '• Google（Google 登录、通过 Firebase 推送通知）',
    'privacy_s4_bullet2': '• 第三方支付服务商，用于安全处理购买',
    'privacy_s4_bullet3': '• 我们位于欧盟的托管服务商',
    'privacy_s4_note': '\n我们绝不会出于广告目的将你的数据出售或出租给第三方。',
    'privacy_s5_title': '5. 安全与保留',
    'privacy_s5_body':
