    'terms_title': 'Условия использования',
    'terms_last_update': 'Последнее обновление: {year}',
    'terms_s1_title': '1. Принятие условий',
    'terms_s1_body':
        'Создавая аккаунт или используя Binome, вы соглашаетесь с настоящими Условиями использования. Если вы не согласны, пожалуйста, не используйте приложение.',
    'terms_s2_title': '2. Кто может использовать Binome',
    'terms_s2_body':
        'Binome предназначен для лиц от 16 лет в рамках добровольных отношений пары. Каждый аккаунт персональный; передача учётных данных запрещена.',
    'terms_s3_title': '3. Ваш аккаунт',
    'terms_s3_body':
        'Вы несёте ответственность за конфиденциальность своих учётных данных и за любые действия, совершённые с вашего аккаунта. Немедленно сообщите нам о несанкционированном доступе.',
    'terms_s4_title': '4. Связь пары («Box»)',
    'terms_s4_body':
        'Присоединение к Box или его создание устанавливает связь, эксклюзивную для двух людей. Вы можете разорвать эту связь в любой момент в Настройках → Опасная зона; общий контент (стихи, фото, ответы в играх...) при этом удаляется безвозвратно.',
    'terms_s5_title': '5. Контент, которым вы делитесь',
    'terms_s5_body1':
        'Вы остаётесь владельцем контента, который отправляете своему бином (сообщения, фото, стихи, ответы в играх). Вы предоставляете нам только техническое право хранить его и передавать вашему бином, но никогда не использовать в иных целях.',
    'terms_s5_body2':
        'Вы обязуетесь не отправлять незаконный, оскорбительный контент или контент, нарушающий права третьих лиц.',
    'terms_s6_title': '6. Виртуальные монеты и покупки',
    'terms_s6_body':
        'Binome предлагает виртуальные монеты для покупки, используемые для некоторых функций магазина. Покупки обрабатываются нашим сторонним платёжным провайдером. Монеты не имеют реальной денежной ценности и не подлежат возврату или передаче, за исключением случаев, предусмотренных законом.',
    'terms_s7_title': '7. Приостановка и прекращение',
    'terms_s7_body':
        'Мы можем приостановить или удалить аккаунт при явном нарушении настоящих условий (незаконный контент, домогательства, мошенничество). Вы можете удалить свой аккаунт в любой момент в Настройках → Опасная зона.',
    'terms_s8_title': '8. Доступность сервиса',
    'terms_s8_body':
        'Мы делаем всё возможное, чтобы Binome оставался доступным, но не гарантируем бесперебойную доступность. Сервис может развиваться, временно приостанавливаться для обслуживания или изменяться.',
    'terms_s9_title': '9. Ограничение ответственности',
    'terms_s9_body':
        'Binome предоставляется «как есть». В пределах, допустимых законом, мы не несём ответственности за косвенный ущерб, возникший в результате использования приложения.',
    'terms_s10_title': '10. Изменения',
    'terms_s10_body':
        'Эти условия могут изменяться; о любом существенном изменении вам будет сообщено в приложении.',
    'terms_s11_title': '11. Контакты',
    'terms_s11_body':
        'По любым вопросам об этих условиях: contact@binome-app.com.',
    'common_enable': 'Включить',
    'notif_card_title': 'Уведомления отключены',
    'notif_card_subtitle':
        'Включите их, чтобы не пропустить ничего от своего бином.',
    'notif_dialog_title': 'Включите уведомления',
    'notif_dialog_subtitle': 'Чтобы не пропустить своего бином',
    'notif_dialog_benefit_dates': 'Особые даты',
    'notif_dialog_benefit_heartbeats': 'Биения сердца',
    'notif_dialog_benefit_gifts': 'Подарки',
    'common_cancel': 'Отмена',
    'contact_title': 'Связаться с нами',
    'contact_subtitle':
        'Есть вопрос, проблема или предложение? Напишите нам, мы ответим по email.',
    'contact_subject_label': 'Тема',
    'contact_message_label': 'Сообщение',
    'contact_send': 'Отправить',
    'contact_sent_snackbar':
        'Сообщение отправлено — мы ответим вам по email. 💕',
    'contact_generic_error': 'Не удалось отправить сообщение сейчас.',
    'privacy_title': 'Политика конфиденциальности',
    'privacy_last_update': 'Последнее обновление: {year}',
    'privacy_s1_title': '1. Кто мы',
    'privacy_s1_body1':
        'Binome — это мобильное приложение для пар, созданное как приватное пространство исключительно для двоих. Эта политика объясняет, какие данные мы собираем, зачем и как вы можете их контролировать.',
    'privacy_s1_body2':
        'По любым вопросам о ваших данных: contact@binome-app.com.',
    'privacy_s2_title': '2. Какие данные мы собираем',
    'privacy_s2_sub1_title': 'Информация об аккаунте',
    'privacy_s2_sub1_body':
        'Email, имя, фамилия, пол, страна проживания, фото профиля, предпочитаемые язык и тема. Если вы входите через Google, часть этой информации поступает напрямую из вашего аккаунта Google.',
    'privacy_s2_sub2_title': 'Информация, связанная с вашей парой («Box»)',
    'privacy_s2_sub2_body':
        'Код сопряжения, дата «вместе с», совместное фото, общий девиз/цитата и ваши настройки напоминаний (вечерние/утренние ритуалы).',
    'privacy_s2_sub3_title': 'Контент, которым вы обмениваетесь',
    'privacy_s2_sub3_body':
        'Стихи, подарки, сообщения, фото, ответы в играх, реакции — всё, что вы отправляете своему бином внутри приложения.',
    'privacy_s2_sub4_title': 'Платёжные данные',
    'privacy_s2_sub4_body':
        'При покупке виртуальных монет платёжная информация обрабатывается напрямую нашим сторонним платёжным провайдером; мы никогда не храним полные банковские данные, только историю ваших транзакций (сумма, валюта, дата).',
    'privacy_s2_sub5_title': 'Технические данные',
    'privacy_s2_sub5_body':
        'Токен push-уведомлений (для отправки напоминаний), отметка времени последней активности и информация об устройстве, необходимая для корректной работы сервиса.',
    'privacy_s3_title': '3. Как мы используем эти данные',
    'privacy_s3_bullet1': '• Для работы вашего аккаунта и пространства пары',
    'privacy_s3_bullet2':
        '• Для отправки включённых вами уведомлений (напоминания, оповещения)',
    'privacy_s3_bullet3': '• Для обработки покупок виртуальных монет',
    'privacy_s3_bullet4':
        '• Для обеспечения безопасности и предотвращения злоупотреблений',
    'privacy_s3_bullet5': '• Для улучшения приложения',
    'privacy_s3_note':
        '\nМы никогда не используем переписку вашей пары (сообщения, стихи, фото) для рекламы или контента, созданного ИИ.',
    'privacy_s4_title': '4. Передача третьим лицам',
    'privacy_s4_intro':
        'Ваши данные могут передаваться, строго в необходимых пределах:',
    'privacy_s4_bullet1':
        '• Google (вход через Google Sign-In, push-уведомления через Firebase)',
