    'terms_title': 'Hizmet Şartları',
    'terms_last_update': 'Son güncelleme: {year}',
    'terms_s1_title': '1. Şartların kabulü',
    'terms_s1_body':
        'Bir hesap oluşturarak veya Binome\'u kullanarak bu Hizmet Şartlarını kabul etmiş olursun. Kabul etmiyorsan lütfen uygulamayı kullanma.',
    'terms_s2_title': '2. Binome\'u kimler kullanabilir',
    'terms_s2_body':
        'Binome, karşılıklı rızaya dayalı bir çift ilişkisi bağlamında 16 yaş ve üzeri kişilere yöneliktir. Her hesap kişiseldir; giriş bilgilerinin paylaşılması yasaktır.',
    'terms_s3_title': '3. Hesabın',
    'terms_s3_body':
        'Giriş bilgilerinin gizliliğinden ve hesabından yapılan her türlü işlemden sorumlusun. Yetkisiz erişim durumunda bize hemen haber ver.',
    'terms_s4_title': '4. Çift bağlantısı ("Box")',
    'terms_s4_body':
        'Bir Box\'a katılmak veya oluşturmak, iki kişiye özel bir bağlantı kurar. Bu bağlantıyı istediğiniz zaman Ayarlar → Tehlikeli bölge üzerinden sonlandırabilirsiniz; paylaşılan içerikler (şiirler, fotoğraflar, oyun cevapları...) o zaman kalıcı olarak silinir.',
    'terms_s5_title': '5. Paylaştığın içerik',
    'terms_s5_body1':
        'Binômene gönderdiğin içeriğin (mesajlar, fotoğraflar, şiirler, oyun cevapları) sahibi olarak kalırsın. Bize yalnızca bunu barındırma ve binômene iletme konusunda teknik hak verirsin, başka amaçlarla kullanma hakkı vermezsin.',
    'terms_s5_body2':
        'Yasa dışı, taciz edici veya üçüncü tarafların haklarını ihlal eden içerik göndermemeyi kabul edersin.',
    'terms_s6_title': '6. Sanal jetonlar ve satın alımlar',
    'terms_s6_body':
        'Binome, Mağaza\'nın bazı özellikleri için kullanılabilen satın alınabilir sanal jetonlar sunar. Satın alımlar üçüncü taraf ödeme sağlayıcımız tarafından işlenir. Jetonların gerçek parasal değeri yoktur ve yasal zorunluluk olmadıkça iade edilemez veya devredilemez.',
    'terms_s7_title': '7. Askıya alma ve fesih',
    'terms_s7_body':
        'Bu şartların açıkça ihlali durumunda (yasa dışı içerik, taciz, dolandırıcılık) bir hesabı askıya alabilir veya silebiliriz. Hesabını istediğin zaman Ayarlar → Tehlikeli bölge üzerinden silebilirsin.',
    'terms_s8_title': '8. Hizmetin kullanılabilirliği',
    'terms_s8_body':
        'Binome\'u erişilebilir tutmak için elimizden geleni yaparız, ancak kesintisiz kullanılabilirlik garanti etmeyiz. Hizmet zamanla değişebilir, bakım için geçici olarak durdurulabilir veya değiştirilebilir.',
    'terms_s9_title': '9. Sorumluluğun sınırlandırılması',
    'terms_s9_body':
        'Binome "olduğu gibi" sunulur. Yasaların izin verdiği ölçüde, uygulamanın kullanımından kaynaklanan dolaylı zararlardan sorumlu değiliz.',
    'terms_s10_title': '10. Değişiklikler',
    'terms_s10_body':
        'Bu şartlar zaman içinde değişebilir; önemli her değişiklik uygulama içinde sana bildirilecektir.',
    'terms_s11_title': '11. İletişim',
    'terms_s11_body':
        'Bu şartlarla ilgili herhangi bir soru için: contact@binome-app.com.',
