    'terms_title': 'Умови використання',
    'terms_last_update': 'Останнє оновлення: {year}',
    'terms_s1_title': '1. Прийняття умов',
    'terms_s1_body':
        'Створюючи акаунт або використовуючи Binome, ви погоджуєтесь із цими Умовами використання. Якщо ви не погоджуєтесь, будь ласка, не використовуйте застосунок.',
    'terms_s2_title': '2. Хто може використовувати Binome',
    'terms_s2_body':
        'Binome призначений для осіб віком від 16 років у межах добровільних стосунків пари. Кожен акаунт є персональним; передавати облікові дані заборонено.',
    'terms_s3_title': '3. Ваш акаунт',
    'terms_s3_body':
        'Ви несете відповідальність за конфіденційність своїх облікових даних і за будь-яку діяльність, здійснену з вашого акаунта. Негайно повідомте нас у разі несанкціонованого доступу.',
    'terms_s4_title': '4. Зв\'язок пари («Box»)',
    'terms_s4_body':
        'Приєднання до Box або його створення встановлює зв\'язок, ексклюзивний для двох людей. Ви можете розірвати цей зв\'язок у будь-який момент у Налаштуваннях → Небезпечна зона; спільний контент (вірші, фото, відповіді в іграх...) тоді видаляється остаточно.',
    'terms_s5_title': '5. Контент, яким ви ділитеся',
    'terms_s5_body1':
        'Ви залишаєтесь власником контенту, який надсилаєте своєму біному (повідомлення, фото, вірші, відповіді в іграх). Ви надаєте нам лише технічне право розміщувати його та передавати вашому біному, але ніколи не використовувати з іншою метою.',
    'terms_s5_body2':
        'Ви зобов\'язуєтесь не надсилати незаконний, такий що переслідує, контент або контент, що порушує права третіх осіб.',
    'terms_s6_title': '6. Віртуальні монети та покупки',
    'terms_s6_body':
        'Binome пропонує віртуальні монети для покупки, які використовуються для деяких функцій магазину. Покупки обробляються нашим стороннім платіжним провайдером. Монети не мають реальної грошової вартості та не підлягають поверненню чи передачі, крім випадків, передбачених законом.',
    'terms_s7_title': '7. Призупинення та припинення',
    'terms_s7_body':
        'Ми можемо призупинити або видалити акаунт у разі явного порушення цих умов (незаконний контент, переслідування, шахрайство). Ви можете видалити свій акаунт у будь-який момент у Налаштуваннях → Небезпечна зона.',
    'terms_s8_title': '8. Доступність сервісу',
    'terms_s8_body':
        'Ми докладаємо всіх зусиль, щоб Binome залишався доступним, але не гарантуємо безперервну доступність. Сервіс може розвиватися, тимчасово призупинятися для обслуговування або змінюватися.',
    'terms_s9_title': '9. Обмеження відповідальності',
    'terms_s9_body':
        'Binome надається "як є". У межах, дозволених законом, ми не несемо відповідальності за непрямі збитки, що виникли внаслідок використання застосунку.',
    'terms_s10_title': '10. Зміни',
    'terms_s10_body':
        'Ці умови можуть змінюватися; про будь-яку суттєву зміну вам буде повідомлено в застосунку.',
    'terms_s11_title': '11. Контакти',
    'terms_s11_body':
        'З будь-яким питанням щодо цих умов: contact@binome-app.com.',
