    'privacy_title': 'Політика конфіденційності',
    'privacy_last_update': 'Останнє оновлення: {year}',
    'privacy_s1_title': '1. Хто ми',
    'privacy_s1_body1':
        'Binome — мобільний застосунок для пар, створений як приватний простір, ексклюзивний лише для двох людей. Ця політика пояснює, які дані ми збираємо, навіщо і як ви можете їх контролювати.',
    'privacy_s1_body2':
        'З будь-яким питанням щодо ваших даних: contact@binome-app.com.',
    'privacy_s2_title': '2. Дані, які ми збираємо',
    'privacy_s2_sub1_title': 'Інформація про акаунт',
    'privacy_s2_sub1_body':
        'Email, ім\'я, прізвище, стать, країна проживання, фото профілю, бажані мова та тема. Якщо ви входите через Google, частина цієї інформації надходить безпосередньо з вашого акаунта Google.',
    'privacy_s2_sub2_title': 'Інформація, пов\'язана з вашою парою («Box»)',
    'privacy_s2_sub2_body':
        'Код з\'єднання, дата «разом з», спільне фото, спільний девіз/цитата та ваші налаштування нагадувань (вечірні/ранкові ритуали).',
    'privacy_s2_sub3_title': 'Контент, яким ви обмінюєтеся',
    'privacy_s2_sub3_body':
        'Вірші, подарунки, повідомлення, фото, відповіді в іграх, реакції — все, що ви надсилаєте своєму біному в застосунку.',
    'privacy_s2_sub4_title': 'Платіжні дані',
    'privacy_s2_sub4_body':
        'Якщо ви купуєте віртуальні монети, платіжна інформація обробляється безпосередньо нашим стороннім платіжним провайдером; ми ніколи не зберігаємо ваші повні банківські дані, лише історію транзакцій (сума, валюта, дата).',
    'privacy_s2_sub5_title': 'Технічні дані',
    'privacy_s2_sub5_body':
        'Токен push-сповіщень (для надсилання нагадувань), позначка часу останньої активності та інформація про пристрій, необхідна для належної роботи сервісу.',
    'privacy_s3_title': '3. Як ми використовуємо ці дані',
    'privacy_s3_bullet1': '• Для роботи вашого акаунта та простору пари',
    'privacy_s3_bullet2':
        '• Для надсилання ввімкнених вами сповіщень (нагадування, оповіщення)',
    'privacy_s3_bullet3': '• Для обробки покупок віртуальних монет',
    'privacy_s3_bullet4':
        '• Для забезпечення безпеки та запобігання зловживанням',
    'privacy_s3_bullet5': '• Для покращення застосунку',
    'privacy_s3_note':
        '\nМи ніколи не використовуємо листування вашої пари (повідомлення, вірші, фото) для реклами чи контенту, згенерованого ШІ.',
    'privacy_s4_title': '4. Передача третім особам',
    'privacy_s4_intro':
        'Ваші дані можуть передаватися, лише в необхідних межах, до:',
    'privacy_s4_bullet1':
        '• Google (вхід через Google Sign-In, push-сповіщення через Firebase)',
    'privacy_s4_bullet2':
        '• Стороннього платіжного провайдера — для безпечної обробки покупок',
    'privacy_s4_bullet3':
        '• Нашого хостинг-провайдера, розташованого в Європейському Союзі',
    'privacy_s4_note':
        '\nМи ніколи не продаємо і не здаємо в оренду ваші дані третім особам з рекламною метою.',
    'privacy_s5_title': '5. Безпека та зберігання',
    'privacy_s5_body':
        'Ваші дані зберігаються на серверах, розташованих у Європейському Союзі, із шифруванням паролів і токенів автентифікації. Вони зберігаються, доки ваш акаунт активний, і остаточно видаляються (разом з даними вашого Box, каскадно) у разі видалення акаунта.',
    'privacy_s6_title': '6. Ваші права',
    'privacy_s6_intro': 'У будь-який момент ви можете:',
    'privacy_s6_bullet1':
        '• Переглядати та редагувати інформацію свого профілю',
    'privacy_s6_bullet2':
        '• Остаточно видалити акаунт у Налаштуваннях → Небезпечна зона',
    'privacy_s6_bullet3':
        '• Звернутися до нас з будь-яким питанням щодо ваших даних',
    'privacy_s7_title': '7. Мінімальний вік',
    'privacy_s7_body': 'Binome призначений для осіб віком від 16 років.',
    'privacy_s8_title': '8. Зміни',
