    'privacy_title': 'プライバシーポリシー',
    'privacy_last_update': '最終更新日：{year}',
    'privacy_s1_title': '1. 私たちについて',
    'privacy_s1_body1':
        'Binomeはカップルのために作られたモバイルアプリで、二人だけのプライベートな空間であり続けることを目指しています。本ポリシーでは、どのようなデータを、なぜ収集するか、そしてどのように管理できるかを説明します。',
    'privacy_s1_body2': 'データに関するご質問は：contact@binome-app.com まで。',
    'privacy_s2_title': '2. 収集するデータ',
    'privacy_s2_sub1_title': 'アカウント情報',
    'privacy_s2_sub1_body':
        'メールアドレス、名、姓、性別、居住国、プロフィール写真、希望する言語とテーマ。Googleでログインする場合、これらの情報の一部はGoogleアカウントから直接取得されます。',
    'privacy_s2_sub2_title': 'カップル（「Box」）に関連する情報',
    'privacy_s2_sub2_body':
        'ペアリングコード、「付き合い始めた日」、カップル写真、共有のモットー/引用、そしてリマインダー設定（夜/朝の習慣）。',
    'privacy_s2_sub3_title': 'やり取りするコンテンツ',
    'privacy_s2_sub3_body':
        '詩、贈り物、メッセージ、写真、ゲームの回答、リアクション——アプリ内でバイノームに送るすべてのもの。',
    'privacy_s2_sub4_title': '決済データ',
    'privacy_s2_sub4_body':
        '仮想コインを購入する場合、決済情報は第三者の決済プロバイダーによって直接処理されます。銀行情報の全体を保存することはなく、取引履歴（金額、通貨、日付）のみを保持します。',
    'privacy_s2_sub5_title': '技術データ',
    'privacy_s2_sub5_body':
        'プッシュ通知トークン（リマインダー送信用）、最終アクティビティのタイムスタンプ、およびサービスの正常な動作に必要な端末情報。',
    'privacy_s3_title': '3. データの利用方法',
    'privacy_s3_bullet1': '• アカウントとカップルスペースを機能させるため',
    'privacy_s3_bullet2': '• 有効にした通知（リマインダー、アラート）を送信するため',
    'privacy_s3_bullet3': '• 仮想コインの購入を処理するため',
    'privacy_s3_bullet4': '• セキュリティを確保し、不正利用を防止するため',
    'privacy_s3_bullet5': '• アプリを改善するため',
    'privacy_s3_note':
        '\nカップル間のやり取り（メッセージ、詩、写真）を広告目的やAI生成コンテンツのために使用することはありません。',
    'privacy_s4_title': '4. 第三者への提供',
    'privacy_s4_intro': 'データは、必要な範囲に限り、以下に共有される場合があります：',
    'privacy_s4_bullet1': '• Google（Googleログイン、Firebase経由のプッシュ通知）',
    'privacy_s4_bullet2': '• 安全な購入処理のための第三者決済プロバイダー',
    'privacy_s4_bullet3': '• 欧州連合（EU）内にあるホスティングプロバイダー',
    'privacy_s4_note': '\n広告目的でデータを第三者に販売または貸与することは決してありません。',
    'privacy_s5_title': '5. セキュリティとデータの保持',
    'privacy_s5_body':
        'データは、パスワードと認証トークンを暗号化した状態で、欧州連合（EU）内のサーバーに保存されます。アカウントが有効な間は保持され、アカウントを削除すると（Boxのデータも連鎖的に）完全に削除されます。',
    'privacy_s6_title': '6. あなたの権利',
    'privacy_s6_intro': 'いつでも次のことができます：',
    'privacy_s6_bullet1': '• プロフィール情報の確認・編集',
    'privacy_s6_bullet2': '• 設定 → 危険ゾーンからアカウントを完全に削除',
    'privacy_s6_bullet3': '• データに関するご質問はお問い合わせ',
    'privacy_s7_title': '7. 最低年齢',
    'privacy_s7_body': 'Binomeは16歳以上の方を対象としています。',
